const STORAGE='svca-academy-v1';
// Some browsers restrict localStorage on file:// pages. Keep the academy usable
// in that case and fall back to an in-memory session.
const storage={get(key){try{return window.localStorage.getItem(key)}catch{return null}},set(key,value){try{window.localStorage.setItem(key,value);return true}catch{return false}}};
let state={};try{state=JSON.parse(storage.get(STORAGE)||'{}')}catch{state={}}
state.completed ||= [];state.favorites ||= [];state.notes ||= '';state.streak ||= 0;state.lastVisit ||= '';state.xp ||= 0;state.history ||= [];state.quizStats ||= {};
let currentView='home',searchTerm='';
const $=s=>document.querySelector(s), content=$('#appContent');
const today=new Date().toISOString().slice(0,10);if(state.lastVisit!==today){const y=new Date(Date.now()-86400000).toISOString().slice(0,10);state.streak=state.lastVisit===y?(state.streak||0)+1:1;state.lastVisit=today;save()}
function save(){storage.set(STORAGE,JSON.stringify(state));updateStats();buildModuleNav()}
function updateStats(){const all=chapters.length,done=state.completed.length;$('#streakCount').textContent=state.streak||0;const profile=$('#sidebarLevel');if(profile)profile.textContent=`Niveau ${Math.floor((state.xp||0)/100)+1} · ${state.xp||0} XP`;const glossaryCount=document.querySelector('.nav-count');if(glossaryCount)glossaryCount.textContent=Object.keys(terms).length}
function moduleChapters(id){return chapters.filter(c=>c.module===id)}
function progress(id){const c=moduleChapters(id);return c.length?Math.round(c.filter(x=>state.completed.includes(x.id)).length/c.length*100):0}
function setNav(view){currentView=view;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('.module-link').forEach(b=>b.classList.toggle('current',b.dataset.module===String(view).replace('module-','')));}
function closeMobileSidebar(){if(innerWidth<800){$('#sidebar').classList.remove('open');$('#menuToggle').setAttribute('aria-expanded','false');$('#menuToggle').setAttribute('aria-label','Ouvrir le menu')}}
function buildModuleNav(){const box=$('#moduleNav');box.innerHTML=modules.map(m=>`<button class="module-link" data-module="${m.id}"><span class="module-dot"></span><span>Module ${String(m.id).padStart(2,'0')}</span><span class="module-status">${progress(m.id)?`${progress(m.id)}%`:'›'}</span></button>`).join('');box.querySelectorAll('.module-link').forEach(b=>b.onclick=()=>{closeMobileSidebar();showModule(+b.dataset.module)})}
function chapterRow(c){const done=state.completed.includes(c.id),active=!done&&chapters.find(x=>!state.completed.includes(x.id))?.id===c.id;return `<button class="chapter-row" data-chapter="${c.id}"><span class="chapter-index">${c.id}</span><span class="chapter-name">${c.title}</span><span class="chapter-meta"><span>${c.time}</span><span class="chapter-state ${done?'done':active?'active':''}">${done?'✓':active?'›':''}</span></span></button>`}
function renderHome(){setNav('home');$('#crumbCurrent').textContent='Vue d’ensemble';const done=state.completed.length,total=chapters.length,first=chapters.find(c=>!state.completed.includes(c.id))||chapters[0],percent=Math.round(done/total*100);content.innerHTML=`<section class="hero"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow">L’ACADÉMIE DU VIBE CODING</span><h1>Construisez avec l’IA.<br/><span>Comprenez chaque étape.</span></h1><p>Le parcours francophone pour passer de « je ne sais pas par où commencer » à « je sais piloter et vérifier mon produit ». Sans jargon oublié, sans étapes sautées.</p><button class="button primary" data-chapter="${first.id}">Continuer mon parcours <span>→</span></button><div class="hero-meta"><span>◉ <b>Modules 00–01</b> disponibles</span><span>◷ <b>${total} chapitres</b> guidés</span><span>✦ <b>À votre rythme</b></span></div></div><div class="hero-visual"><div class="orbit one"></div><div class="orbit two"></div><div class="orbit three"></div><div class="core">✳</div><i class="orb-dot d1"></i><i class="orb-dot d2"></i><i class="orb-dot d3"></i></div></div></section>
<section class="stats-grid"><article class="stat-card"><div class="stat-label">Progression globale <i>◫</i></div><div class="stat-value">${percent}<span style="font-size:12px;color:#98a8c1">%</span></div><div class="stat-sub">${done} chapitre${done>1?'s':''} validé${done>1?'s':''} sur ${total}</div></article><article class="stat-card"><div class="stat-label">Points d’expérience <i>✦</i></div><div class="stat-value">${state.xp}<span style="font-size:12px;color:#98a8c1"> XP</span></div><div class="stat-sub">Prochain niveau : <em>${Math.max(0,100-(state.xp%100))} XP</em></div></article><article class="stat-card"><div class="stat-label">Niveau actuel <i>↗</i></div><div class="stat-value" style="font-size:18px">${Math.floor(state.xp/100)+1} <span style="font-size:12px;color:#98a8c1;font-weight:500">· Explorateur</span></div><div class="stat-sub">Chaque leçon vous rapproche du suivant</div></article><article class="stat-card"><div class="stat-label">Série d’apprentissage <i>ϟ</i></div><div class="stat-value">${state.streak}<span style="font-size:12px;color:#98a8c1"> j</span></div><div class="stat-sub"><em>Votre rythme, votre réussite</em></div></article></section>
<section class="section-heading"><div><h2>Votre parcours</h2><p>Des fondations solides, une idée à la fois.</p></div><button class="text-button" data-view="path">Voir le parcours complet →</button></section><section class="learning-grid"><article class="module-card"><div class="module-card-head"><div><span class="module-tag"><span class="module-dot"></span> MODULE 00 · FONDATIONS</span><h3>Préparation mentale</h3><p>La posture pour utiliser l’IA sans lui abandonner vos décisions.</p></div><div class="module-progress-wrap"><strong>${progress(0)}%</strong><div class="module-progress"><span style="width:${progress(0)}%"></span></div></div></div><div class="chapter-list">${moduleChapters(0).map(chapterRow).join('')}</div></article><aside class="continue-card"><span class="eyebrow">${state.completed.length?'REPRENDRE':'PREMIÈRE ÉTAPE'}</span><h3>${first.title}</h3><p>${first.lead}</p><div class="continue-illustration"><div class="stack-cards"><span>01</span><span>02</span><span>03</span></div></div><button class="button" data-chapter="${first.id}">Ouvrir le chapitre <span>→</span></button></aside></section>
<section class="section-heading"><div><h2>Vos fondations d’Internet</h2><p>Comprenez ce qui se passe derrière chaque site.</p></div><button class="text-button" data-module="1">Explorer le module →</button></section><section class="module-card" style="margin-bottom:30px"><div class="module-card-head"><div><span class="module-tag"><span class="module-dot"></span> MODULE 01 · LES BASES</span><h3>Comprendre Internet</h3><p>Des réseaux aux serveurs : suivez la route d’une information sur le web.</p></div><div class="module-progress-wrap"><strong>${progress(1)}%</strong><div class="module-progress"><span style="width:${progress(1)}%"></span></div></div></div><div class="chapter-list">${moduleChapters(1).slice(0,4).map(chapterRow).join('')}<button class="chapter-row" data-module="1" style="justify-content:center;color:#91aaff;font-size:9px">Voir les 8 chapitres du module <span>→</span></button></div></section>
<section class="section-heading"><div><h2>Apprendre autrement</h2><p>Des outils pour que les idées restent avec vous.</p></div></section><section class="quick-links"><button class="quick-card" data-view="mindmap"><span class="quick-icon">✳</span><span><strong>Carte mentale</strong><small>Relier les concepts clés</small></span></button><button class="quick-card" data-view="glossary"><span class="quick-icon">Aa</span><span><strong>Dictionnaire</strong><small>Le jargon, enfin expliqué</small></span></button><button class="quick-card" id="openNotesCard"><span class="quick-icon">▤</span><span><strong>Mes notes</strong><small>Vos idées, à portée de main</small></span></button></section>`;wireContent()}
function showModule(id){setNav(`module-${id}`);const m=modules[id];const nextChapter=moduleChapters(id).find(c=>!state.completed.includes(c.id)),nextModule=modules.find(m=>m.id>id),moduleCta=nextChapter?'<button class="button primary" data-chapter="'+nextChapter.id+'">Continuer &middot; '+nextChapter.id+' <span>&rarr;</span></button>':nextModule?'<button class="button primary" data-module="'+nextModule.id+'">Module suivant &middot; '+String(nextModule.id).padStart(2,'0')+' <span>&rarr;</span></button>':'<button class="button primary" data-view="achievements">Voir mes acquis <span>&rarr;</span></button>';$('#crumbCurrent').textContent=`Module ${String(id).padStart(2,'0')}`;content.innerHTML=`<div class="page-header"><span class="eyebrow">MODULE ${String(id).padStart(2,'0')} · PARCOURS</span><h1>${m.title}</h1><p>${m.desc}</p></div><div class="path-grid"><article class="path-module open"><div class="path-head"><span class="path-number">${String(id).padStart(2,'0')}</span><span><h3>${m.title}</h3><p>${m.subtitle}</p></span><span class="path-trail">${progress(id)}% complété · ${moduleChapters(id).length} chapitres</span></div><div class="path-body">${moduleChapters(id).map(c=>`<button class="path-node" data-chapter="${c.id}"><span>${c.id}</span><strong>${c.title}</strong><small>${c.time} ${state.completed.includes(c.id)?' · ✓':''}</small></button>`).join('')}</div></article></div><div class="complete-panel" style="margin-top:18px"><div><strong>${moduleChapters(id).filter(c=>state.completed.includes(c.id)).length}/${moduleChapters(id).length} chapitres validés</strong><p>Avancez à votre rythme. Chaque chapitre reprend les bases avant d’aller plus loin.</p></div>${moduleCta}</div>`;wireContent()}
const sectionId=t=>t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-');
function termify(text){const keys=Object.keys(terms).sort((a,b)=>b.length-a.length);if(!keys.length)return text;const matcher=new RegExp(`(^|[^\\p{L}\\p{N}_])(${keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')})(?=$|[^\\p{L}\\p{N}_])`,'giu');return text.replace(matcher,(whole,before,word)=>{const key=keys.find(k=>k.toLowerCase()===word.toLowerCase())||word;return `${before}<button type="button" class="term" data-term="${key}">${word}</button>`})}
function diagram(c){return `<div class="diagram interactive-diagram" data-sim="${c.id}"><div class="diagram-flow">${c.diagram.map((n,i)=>`${i?'<span class="flow-arrow">→</span>':''}<button class="flow-node diagram-step" data-step="${i}">${n[0]}<small>${n[1]}</small></button>`).join('')}</div><div class="diagram-caption">Chaque élément joue un rôle dans le parcours de l’information.</div><div class="sim-controls"><button class="button sim-start" data-simstart="${c.id}">▶ Voir le parcours</button><button class="button sim-reset" data-simreset="${c.id}">↺ Recommencer</button></div><div class="sim-status" aria-live="polite">Sélectionnez une étape pour l’explorer.</div></div>`}
function quiz(c){return `<div class="quiz" data-quiz="${c.id}"><span class="quiz-label">VÉRIFIER SA COMPRÉHENSION</span><h3>${c.quiz.q}</h3>${c.quiz.options.map((o,i)=>`<button class="quiz-option" data-answer="${i}">${o}</button>`).join('')}<div class="quiz-feedback"></div></div>`}
function lessonSection(title,body){return `<section class="learn-section" id="${sectionId(title)}"><h2>${title}</h2>${body}</section>`}
function renderLesson(c){setNav(`module-${c.module}`);$('#crumbCurrent').textContent=`${c.id} · ${c.title}`;const done=state.completed.includes(c.id),mod=modules[c.module];const lessonIndex=chapters.findIndex(x=>x.id===c.id),nextChapter=chapters[lessonIndex+1]||null;const sections=[['Pourquoi ce sujet existe',`<div class="why-card"><span class="why-icon">✦</span><div><strong>La bonne question avant la technique</strong><p>${termify(c.why)}</p></div></div><p>${termify(c.problem)}</p>`],['L’analogie du quotidien',`<div class="analogy"><label>IMAGINEZ</label><p>${termify(c.analogy)}</p></div>`],['Visualiser le concept',diagram(c)],['Comprendre à son rythme',`<div class="level-grid"><article class="level-card"><span>01 · L’ESSENTIEL</span><strong>En termes simples</strong><p>${termify(c.simple)}</p></article><article class="level-card"><span>02 · UN PEU PLUS LOIN</span><strong>Explication intermédiaire</strong><p>${termify(c.intermediate)}</p></article><article class="level-card"><span>03 · POUR ALLER PLUS LOIN</span><strong>Explication avancée</strong><p>${termify(c.advanced)}</p></article></div>`],['Les mots à connaître',`<div class="jargon-list">${c.terms.map(t=>`<div class="jargon-item"><button data-term="${t}">${t}</button><small>${terms[t]?.[0]||'Un terme technique expliqué dans le dictionnaire.'}</small><span>Voir la fiche →</span></div>`).join('')}</div>`],['À vous de jouer',`<p>${termify(c.exercise)}</p><div class="analogy"><label>MISE EN SITUATION</label><p>${termify(c.simulation)}</p></div>`],['Quiz de compréhension',quiz(c)],['Résumé visuel',`<div class="diagram"><div class="diagram-flow">${c.mind.split(' → ').map((x,i)=>`${i?'<span class="flow-arrow">→</span>':''}<span class="flow-node">${x}</span>`).join('')}</div><div class="diagram-caption">Le modèle mental à retenir pour ce chapitre.</div></div><p><strong>${termify(c.summary)}</strong></p>`],['Carte mentale',`<div class="analogy"><label>LES LIENS ENTRE LES IDÉES</label><p>${termify(c.mind)}</p></div>`],['Fiche anti-jargon',`<p>Retenez les termes en les expliquant à quelqu’un qui découvre le sujet. Touchez un mot souligné pour sa fiche complète.</p><div class="jargon-list">${c.terms.slice(0,4).map(t=>`<div class="jargon-item"><button data-term="${t}">${t}</button><small>${terms[t]?.[1]||''}</small><span>Analogie</span></div>`).join('')}</div>`],['Flashcards',`<p>Essayez de répondre avant de retourner la carte.</p><div class="flashcards">${c.cards.map((f,i)=>`<button class="flashcard" data-front="${f[0]}" data-back="${f[1]}"><strong>${f[0]}</strong><span>Toucher pour révéler la réponse</span></button>`).join('')}</div>`],['Un cas réel',`<div class="why-card"><span class="why-icon">◎</span><div><strong>Dans un produit réel</strong><p>${termify(c.case)}</p></div></div>`]];
content.innerHTML=`<div class="lesson-top"><button class="back-link" data-module="${c.module}">← Module ${String(c.module).padStart(2,'0')} · ${mod.title}</button><div class="lesson-actions"><button class="favorite-button ${state.favorites.includes(c.id)?'is-saved':''}" data-favorite="${c.id}">${state.favorites.includes(c.id)?'★ Enregistré':'☆ Enregistrer'}</button><button data-notes>▤ Note</button></div></div><span class="eyebrow">CHAPITRE ${c.id} · ${mod.title.toUpperCase()}</span><h1 class="lesson-title">${c.title}</h1><p class="lesson-lead">${c.lead}</p><div class="lesson-meta"><span>◷ ${c.time}</span><span>◫ Pédagogie progressive</span><span>✦ ${done?'Terminé':'+20 XP à la validation'}</span></div><div class="lesson-layout"><article class="lesson-main">${sections.map(([t,b])=>lessonSection(t,b)).join('')}<div class="complete-panel"><div><strong>${done?'Chapitre valid&eacute;':'Avez-vous compris l&#39;essentiel ?'}</strong><p>${done?(nextChapter?'Prochain chapitre : '+nextChapter.id+' &mdash; '+nextChapter.title+'. Votre progression est sauvegard&eacute;e.':'Parcours termin&eacute;. Consultez vos acquis et votre certificat.'):'Validez ce chapitre pour gagner 20 XP et poursuivre votre parcours.'}</p></div>${done?(nextChapter?'<button class="button primary" data-chapter="'+nextChapter.id+'">Chapitre suivant &middot; '+nextChapter.id+' <span>&rarr;</span></button>':'<button class="button primary" data-view="achievements">Voir mes acquis <span>&rarr;</span></button>'):'<button class="button primary" data-complete="'+c.id+'">Valider le chapitre <span>&rarr;</span></button>'}</div></article><aside class="lesson-aside"><div class="aside-card"><h4>DANS CE CHAPITRE</h4>${sections.map(([t])=>`<button class="toc-link" data-scroll="${sectionId(t)}">${t}</button>`).join('')}</div><div class="aside-card"><h4>VOTRE PROGRESSION</h4><div style="font-size:19px;font-weight:700">${progress(c.module)}%</div><small style="color:#8190a7;font-size:8px">Module ${String(c.module).padStart(2,'0')}</small><div class="module-progress" style="width:100%;margin-top:9px"><span style="width:${progress(c.module)}%"></span></div></div></aside></div>`;wireContent()}
function renderMindmap(){setNav('mindmap');$('#crumbCurrent').textContent='Carte mentale';const chain=['Internet','Web','Frontend','Backend','Database','Authentification','Sécurité','Cloud','Déploiement','IA','Architecture SaaS'];const firstChapter=moduleId=>chapters.find(c=>c.module===moduleId)?.id;const mapping={Internet:'1.1',Web:chapters.find(c=>c.title.startsWith('Site web'))?.id,Frontend:chapters.find(c=>c.title.startsWith('Frontend'))?.id,Backend:chapters.find(c=>c.title.startsWith('Backend'))?.id,Database:chapters.find(c=>c.title.startsWith('Base de donn\u00e9es'))?.id,Authentification:firstChapter(6),'S\u00e9curit\u00e9':firstChapter(7),Cloud:chapters.find(c=>c.title.startsWith('Cloud'))?.id,'D\u00e9ploiement':chapters.find(c=>c.title.startsWith('D\u00e9ploiement'))?.id||firstChapter(8),IA:firstChapter(9),'Architecture SaaS':firstChapter(11)};content.innerHTML=`<div class="page-header"><span class="eyebrow">VOTRE VUE D’ENSEMBLE</span><h1>La carte des concepts</h1><p>Une carte vivante des idées qui composent un produit numérique. Tous les n\u0153uds ouvrent un chapitre associ\u00e9 au concept.</p></div><div class="mindmap"><div class="mindmap-branch"><div class="map-root">✳ Un produit numérique</div><div class="map-connect"></div><div class="map-columns">${chain.map((n,i)=>{const id=mapping[n];return `<button class="map-node ${id?'active':'future'}" ${id?`data-chapter="${id}"`:''}><span>${['◉','◫','▤','⌘','▦','◈','◇','☁','↗','✦','⌬'][i]}</span>${n}<small>${id?`Chapitre ${id}`:'À venir'}</small></button>`}).join('')}</div></div></div><div class="map-detail"><span class="muted" style="font-size:9px;color:#8492a8">Suivez la chaîne de gauche à droite ; chaque couche s’appuie sur les précédentes.</span></div><div class="complete-panel"><div><strong>Parcours complet</strong><p>Les 13 modules sont accessibles. Choisissez un th\u00e8me et suivez les chapitres associ\u00e9s.</p></div><button class="button primary" data-view="path">Ouvrir le parcours <span>→</span></button></div>`;wireContent()}
function renderGlossary(){setNav('glossary');$('#crumbCurrent').textContent='Dictionnaire';const entries=Object.entries(terms);content.innerHTML=`<div class="page-header"><span class="eyebrow">LE JARGON, ENFIN EXPLIQUÉ</span><h1>Dictionnaire global</h1><p>Chaque terme propose une explication, une analogie, un exemple et un piège fréquent. Cliquez sur une fiche pour l’ouvrir.</p></div><label class="search-box" style="width:100%;max-width:420px;margin-bottom:18px"><span>⌕</span><input id="glossarySearch" type="search" placeholder="Filtrer les ${entries.length} termes…" aria-label="Filtrer le dictionnaire"/><kbd>Aa</kbd></label><div class="glossary-grid">${entries.map(([name,info])=>`<article class="glossary-card" data-term="${name}"><h3>${name}</h3><p>${info[0]}</p><span>Lire la fiche complète →</span></article>`).join('')}</div><div class="empty-state" id="glossaryEmpty" hidden>Aucun terme ne correspond à votre recherche.</div>`;wireContent();const input=$('#glossarySearch'),cards=[...content.querySelectorAll('.glossary-card')],empty=$('#glossaryEmpty');input.oninput=()=>{const query=input.value.trim().toLocaleLowerCase('fr');let visible=0;for(const card of cards){const show=card.textContent.toLocaleLowerCase('fr').includes(query);card.hidden=!show;if(show)visible++}empty.hidden=visible!==0}}
function renderSaved(){setNav('saved');$('#crumbCurrent').textContent='Mes favoris';const saved=chapters.filter(c=>state.favorites.includes(c.id));content.innerHTML=`<div class="page-header"><span class="eyebrow">VOTRE ESPACE PERSONNEL</span><h1>Mes favoris</h1><p>Les chapitres que vous souhaitez garder à portée de main.</p></div>${saved.length?`<div class="path-grid">${saved.map(c=>`<button class="search-result" data-chapter="${c.id}"><small>CHAPITRE ${c.id} · ${modules[c.module].title}</small><strong>${c.title}</strong><span>${c.lead}</span></button>`).join('')}</div>`:'<div class="empty-state"><strong>Votre collection commence ici</strong>Enregistrez une leçon avec ☆ pour la retrouver facilement.</div>'}`;wireContent()}
function renderSearch(q){searchTerm=q;setNav('');$('#crumbCurrent').textContent='Recherche';const matches=chapters.filter(c=>`${c.id} ${c.title} ${c.lead} ${c.terms.join(' ')} ${c.simple}`.toLowerCase().includes(q.toLowerCase()));const gloss=Object.keys(terms).filter(t=>t.toLowerCase().includes(q.toLowerCase()));content.innerHTML=`<div class="page-header"><span class="eyebrow">RECHERCHE GLOBALE</span><h1>Résultats pour « ${q.replace(/[<>]/g,'')} »</h1><p>${matches.length} chapitre${matches.length!==1?'s':''} et ${gloss.length} terme${gloss.length!==1?'s':''} trouvé${gloss.length!==1?'s':''}.</p></div>${matches.length?`<div class="search-results">${matches.map(c=>`<button class="search-result" data-chapter="${c.id}"><small>CHAPITRE ${c.id} · ${modules[c.module].title} · ${c.time}</small><strong>${c.title}</strong><span>${c.lead}</span></button>`).join('')}</div>`:'<div class="empty-state"><strong>Aucun chapitre trouvé</strong>Essayez un autre mot ou une notion voisine.</div>'}${gloss.length?`<div class="section-heading" style="margin-top:25px"><div><h2>Dans le dictionnaire</h2><p>Ouvrez une fiche pour découvrir une définition, une analogie et un exemple.</p></div></div><div class="glossary-grid">${gloss.slice(0,12).map(t=>`<article class="glossary-card" data-term="${t}"><h3>${t}</h3><p>${terms[t][0]}</p><span>Lire la fiche complète →</span></article>`).join('')}</div>`:''}`;wireContent()}
function openTerm(t){const info=terms[t]||['Explication simple à ajouter au dictionnaire.','Imaginez un outil qui aide à organiser une tâche.','Un produit numérique peut utiliser ce concept.','Vérifiez toujours le rôle précis du terme dans son contexte.'];$('#glossaryBody').innerHTML=`<span class="eyebrow">DICTIONNAIRE · FICHE CONCEPT</span><h2>${t}</h2><div class="definition-block"><label>DÉFINITION ULTRA SIMPLE</label><p>${info[0]}</p></div>${info[4]?`<div class="definition-block"><label>DÉFINITION NORMALE</label><p>${info[4]}</p></div>`:''}<div class="definition-block"><label>ANALOGIE DU QUOTIDIEN</label><p>${info[1]}</p></div><div class="definition-block"><label>EXEMPLE RÉEL</label><p>${info[2]}</p></div><div class="definition-block" style="border:0"><label>PIÈGE FRÉQUENT</label><p>${info[3]}</p></div>`;$('#glossaryDialog').showModal()}
function openNotes(){ $('#notesText').value=state.notes;$('#noteDialog').showModal() }
let toastTimer;function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function wireContent(){content.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{const c=chapters.find(x=>x.id===b.dataset.chapter);if(c)renderLesson(c)});content.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>showModule(+b.dataset.module));content.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));content.querySelectorAll('[data-term]').forEach(b=>b.onclick=()=>openTerm(b.dataset.term));content.querySelectorAll('[data-notes]').forEach(b=>b.onclick=openNotes);const fav=content.querySelector('[data-favorite]');if(fav)fav.onclick=()=>{const id=fav.dataset.favorite;if(state.favorites.includes(id))state.favorites=state.favorites.filter(x=>x!==id);else state.favorites.push(id);save();renderLesson(chapters.find(x=>x.id===id))};content.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{if(!state.completed.includes(b.dataset.complete)){state.completed.push(b.dataset.complete);state.xp+=20;save();toast('Chapitre validé · +20 XP');renderLesson(chapters.find(x=>x.id===b.dataset.complete))}});content.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'}));content.querySelectorAll('[data-quiz]').forEach(q=>q.querySelectorAll('.quiz-option').forEach(opt=>opt.onclick=()=>{if(q.dataset.answered)return;q.dataset.answered='yes';const c=chapters.find(x=>x.id===q.dataset.quiz),ok=+opt.dataset.answer===c.quiz.answer;opt.classList.add(ok?'correct':'wrong');if(!ok)q.querySelector(`[data-answer="${c.quiz.answer}"]`)?.classList.add('correct');q.querySelector('.quiz-feedback').textContent=(ok?'Bonne réponse. ':'Pas tout à fait. ')+c.quiz.explain}));content.querySelectorAll('.flashcard').forEach(card=>card.onclick=()=>{const flipped=card.classList.toggle('flipped');card.querySelector('strong').textContent=flipped?card.dataset.back:card.dataset.front;card.querySelector('span').textContent=flipped?'Toucher pour revenir à la question':'Toucher pour révéler la réponse'});content.querySelectorAll('.interactive-diagram').forEach(diag=>{diag.querySelectorAll('.diagram-step').forEach(s=>s.onclick=()=>{diag.querySelectorAll('.diagram-step').forEach(n=>n.classList.remove('selected'));s.classList.add('selected');diag.querySelector('.sim-status').textContent=`Étape ${+s.dataset.step+1} : ${chapters.find(x=>x.id===diag.dataset.sim).diagram[+s.dataset.step][0]} — ${chapters.find(x=>x.id===diag.dataset.sim).diagram[+s.dataset.step][1]}.`});diag.querySelector('.sim-start').onclick=()=>runSimulation(diag);diag.querySelector('.sim-reset').onclick=()=>{clearInterval(diag._interval);diag.querySelectorAll('.diagram-step').forEach(n=>n.classList.remove('active','selected'));diag.querySelector('.sim-status').textContent='Sélectionnez une étape pour l’explorer.'}});const notesBtn=$('#openNotesCard');if(notesBtn)notesBtn.onclick=openNotes}
function runSimulation(diag){clearInterval(diag._interval);const steps=[...diag.querySelectorAll('.diagram-step')];let i=0;diag.querySelector('.sim-status').textContent='Le parcours commence…';diag._interval=setInterval(()=>{steps.forEach(s=>s.classList.remove('active'));if(i>=steps.length){clearInterval(diag._interval);diag.querySelector('.sim-status').textContent='Parcours terminé. La réponse a atteint sa destination.';return}steps[i].classList.add('active');const c=chapters.find(x=>x.id===diag.dataset.sim);diag.querySelector('.sim-status').textContent=`Étape ${i+1}/${steps.length} : ${c.diagram[i][0]} — ${c.diagram[i][1]}.`;i++},900)}
function navigate(view){if(view==='home')renderHome();else if(view==='path')renderPath();else if(view==='mindmap')renderMindmap();else if(view==='glossary')renderGlossary();else if(view==='saved')renderSaved();else if(view==='history')renderHistory();else if(view==='achievements')renderAchievements()}
function renderPath(){setNav('path');$('#crumbCurrent').textContent='Parcours';content.innerHTML=`<div class="page-header"><span class="eyebrow">VOTRE FEUILLE DE ROUTE</span><h1>Du premier repère au SaaS lancé</h1><p>Les treize modules sont maintenant accessibles. Ouvrez un module pour explorer ses chapitres, puis avancez à votre rythme.</p></div><div class="path-grid">${modules.map(m=>`<article class="path-module ${m.id<2?'open':''}"><button class="path-head" data-pathmodule="${m.id}"><span class="path-number">${String(m.id).padStart(2,'0')}</span><span><h3>${m.title}</h3><p>${m.subtitle}</p></span><span class="path-trail">${progress(m.id)}% · ${moduleChapters(m.id).length} chapitres</span></button><div class="path-body">${moduleChapters(m.id).map(c=>`<button class="path-node" data-chapter="${c.id}"><span>${c.id}</span><strong>${c.title}</strong><small>${c.time}${state.completed.includes(c.id)?' · ✓':''}</small></button>`).join('')}</div></article>`).join('')}</div>`;wireContent();content.querySelectorAll('[data-pathmodule]').forEach(b=>b.onclick=()=>b.closest('.path-module').classList.toggle('open'))}

const renderHomeBase=renderHome;
renderHome=function(){renderHomeBase();const availability=content.querySelector('.hero-meta span b');if(availability)availability.textContent='Modules 00–12';const section=document.createElement('section');section.innerHTML=`<div class="section-heading" style="margin-top:30px"><div><h2>La suite du parcours</h2><p>Les modules 02 à 12 sont maintenant ouverts.</p></div><button class="text-button" data-view="path">Voir la feuille de route →</button></div><div class="quick-links curriculum-shortcuts">${modules.slice(2,5).map(m=>`<button class="quick-card" data-module="${m.id}"><span class="quick-icon">${String(m.id).padStart(2,'0')}</span><span><strong>${m.title}</strong><small>${moduleChapters(m.id).length} chapitres · ${progress(m.id)}% complété</small></span></button>`).join('')}</div>`;content.append(section);wireContent()};

const renderLessonImagesBase=renderLesson;
renderLesson=function(c){renderLessonImagesBase(c);if(c.id==='1.7'){const intro=content.querySelector('#introduction');if(intro)intro.insertAdjacentHTML('afterend',`<section class="learn-section"><h2>Un vrai datacenter</h2><p>Voici deux photographies réelles de salles de serveurs. Repérez les armoires, les câbles et les allées qui permettent aux équipes de maintenir les machines.</p><div class="datacenter-gallery"><figure><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Front_of_server_racks_at_NERSC.jpg/1280px-Front_of_server_racks_at_NERSC.jpg" alt="Allée de rangées de serveurs au centre de calcul NERSC"><figcaption>Serveurs du centre NERSC · <a href="https://commons.wikimedia.org/wiki/File:Front_of_server_racks_at_NERSC.jpg" target="_blank" rel="noreferrer">Derrick Coetzee · CC0</a></figcaption></figure><figure><img src="https://upload.wikimedia.org/wikipedia/commons/d/d5/Datacenter.jpg" alt="Armoires informatiques et câblage dans un datacenter"><figcaption>Salle de serveurs · <a href="https://commons.wikimedia.org/wiki/File:Datacenter.jpg" target="_blank" rel="noreferrer">Wil Weterings · domaine public</a></figcaption></figure></div></section>`)}};

function renderHistory(){setNav('history');$('#crumbCurrent').textContent='Historique';const items=state.history||[];content.innerHTML=`<div class="page-header"><span class="eyebrow">VOTRE PARCOURS PERSONNEL</span><h1>Historique d’apprentissage</h1><p>Retrouvez les leçons récemment ouvertes et les chapitres déjà validés sur cet appareil.</p></div>${items.length?`<div class="search-results">${items.map(entry=>{const c=chapters.find(x=>x.id===entry.id);if(!c)return '';const date=new Date(entry.at);return `<button class="search-result" data-chapter="${c.id}"><small>${date.toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'})} · ${state.completed.includes(c.id)?'VALIDÉ':'CONSULTÉ'}</small><strong>${c.title}</strong><span>Module ${String(c.module).padStart(2,'0')} · ${modules[c.module].title}</span></button>`}).join('')}</div>`:'<div class="empty-state"><strong>Votre historique apparaîtra ici</strong>Ouvrez un chapitre pour commencer à le remplir.</div>'}<div style="margin-top:18px"><button class="button" id="clearHistory">Effacer l’historique</button></div>`;wireContent();$('#clearHistory').onclick=()=>{state.history=[];save();renderHistory();toast('Historique effacé.')}}

function getBadges(){const done=state.completed;return [
 {name:'Premier pas',icon:'✦',detail:'Valider votre premier chapitre.',earned:done.length>=1},
 {name:'Esprit Internet',icon:'◎',detail:'Terminer le module Comprendre Internet.',earned:moduleChapters(1).every(c=>done.includes(c.id))},
 {name:'Gardien des données',icon:'◇',detail:'Terminer le module Sécurité.',earned:moduleChapters(7).every(c=>done.includes(c.id))},
 {name:'Pilote IA',icon:'⌘',detail:'Terminer le module IA de développement.',earned:moduleChapters(9).every(c=>done.includes(c.id))},
 {name:'Architecte SaaS',icon:'⌬',detail:'Terminer le module Architecture SaaS.',earned:moduleChapters(11).every(c=>done.includes(c.id))},
 {name:'Bâtisseur',icon:'↗',detail:'Terminer les projets guidés.',earned:moduleChapters(12).every(c=>done.includes(c.id))}
]}
function renderAchievements(){setNav('achievements');$('#crumbCurrent').textContent='Badges & certificat';const badges=getBadges(),earned=badges.filter(b=>b.earned).length,allDone=chapters.every(c=>state.completed.includes(c.id)),percent=Math.round(state.completed.length/chapters.length*100);content.innerHTML=`<div class="page-header"><span class="eyebrow">PROGRESSION & RECONNAISSANCE</span><h1>Badges & certificat</h1><p>Les badges marquent des étapes concrètes. Le certificat interne se débloque lorsque vous avez validé tous les chapitres du parcours.</p></div><section class="stats-grid"><article class="stat-card"><div class="stat-label">Progression du parcours <i>◫</i></div><div class="stat-value">${percent}%</div><div class="module-progress" style="width:100%;margin-top:9px"><span style="width:${percent}%"></span></div></article><article class="stat-card"><div class="stat-label">Badges obtenus <i>✦</i></div><div class="stat-value">${earned}<span style="font-size:12px;color:#98a8c1"> / ${badges.length}</span></div><div class="stat-sub">En validant les modules</div></article><article class="stat-card"><div class="stat-label">Niveau <i>↗</i></div><div class="stat-value">${Math.floor(state.xp/100)+1}</div><div class="stat-sub">${state.xp} XP accumulés</div></article></section><div class="section-heading"><div><h2>Vos badges</h2><p>Ils se débloquent en validant des étapes du parcours.</p></div></div><div class="quick-links badge-grid">${badges.map(b=>`<article class="quick-card badge-card ${b.earned?'earned':''}"><span class="quick-icon">${b.icon}</span><span><strong>${b.name}</strong><small>${b.detail}</small><small class="badge-status">${b.earned?'Obtenu ✓':'À débloquer'}</small></span></article>`).join('')}</div><section class="certificate-card ${allDone?'earned':''}"><div><span class="eyebrow">CERTIFICATION INTERNE · SENIOR VIBE CODING ACADEMY</span><h2>${allDone?'Parcours validé':'Certificat de fin de parcours'}</h2><p>${allDone?'Vous avez validé les 96 chapitres. Votre certificat interne est prêt.':'Validez les 96 chapitres pour obtenir le certificat interne.'}</p></div><div class="certificate-progress"><strong>${state.completed.length} / ${chapters.length}</strong><small>chapitres validés</small><div class="module-progress"><span style="width:${percent}%"></span></div></div>${allDone?`<button class="button primary" id="printCertificate">Imprimer le certificat <span>↗</span></button>`:''}</section>`;wireContent();const print=$('#printCertificate');if(print)print.onclick=()=>window.print()}

const renderLessonBase=renderLesson;
renderLesson=function(c){state.history=(state.history||[]).filter(x=>x.id!==c.id);state.history.unshift({id:c.id,at:new Date().toISOString()});state.history=state.history.slice(0,100);storage.set(STORAGE,JSON.stringify(state));renderLessonBase(c);const main=content.querySelector('.lesson-main'),first=main?.querySelector('.learn-section');if(!main||!first)return;const intro=document.createElement('section');intro.className='learn-section';intro.id='introduction';intro.innerHTML=`<h2>Introduction</h2><p>${termify(c.lead)}</p>`;first.before(intro);const problemParagraph=first.querySelector('p');if(problemParagraph){const problem=document.createElement('section');problem.className='learn-section';problem.id='probleme-a-resoudre';problem.innerHTML=`<h2>Le problème à résoudre</h2>${problemParagraph.outerHTML}`;problemParagraph.remove();first.after(problem)}const practice=main.querySelector(`#${sectionId('À vous de jouer')}`);if(practice){const simulation=practice.querySelector('.analogy');if(simulation){const guided=document.createElement('section');guided.className='learn-section';guided.id='simulation-guidee';guided.innerHTML=`<h2>Simulation guidée</h2>${simulation.outerHTML}`;simulation.remove();practice.after(guided)}}const flash=main.querySelector(`#${sectionId('Flashcards')}`);if(flash){const review=document.createElement('section');review.className='learn-section';review.id='revision';review.innerHTML='<h2>Révision espacée</h2><p>Refaites ces cartes demain, puis dans trois jours et une semaine. Essayez de répondre avant de retourner chaque carte et revenez à l’explication si un terme reste flou.</p><div class="revision-steps"><span>Demain · rappel court</span><span>Dans 3 jours · relier les idées</span><span>Dans 7 jours · expliquer sans aide</span></div>';flash.after(review)}const complete=main.querySelector('.complete-panel');if(complete){const label=document.createElement('span');label.className='eyebrow';label.textContent='VALIDATION DES ACQUIS';complete.querySelector(':scope > div')?.prepend(label)}};

const renderHomeCompletionBase=renderHome;
renderHome=function(){renderHomeCompletionBase();if(state.completed.length<chapters.length)return;const primary=content.querySelector('.hero-copy [data-chapter]');if(primary){primary.removeAttribute('data-chapter');primary.dataset.view='achievements';primary.innerHTML='Voir mon certificat <span>→</span>'}const card=content.querySelector('.continue-card');if(card){card.querySelector('.eyebrow').textContent='PARCOURS TERMINÉ';card.querySelector('h3').textContent='Félicitations !';card.querySelector('p').textContent='Vous avez validé les 96 chapitres. Consultez vos badges et votre certificat interne.';const button=card.querySelector('[data-chapter]');button.removeAttribute('data-chapter');button.dataset.view='achievements';button.innerHTML='Voir mes acquis <span>→</span>'}wireContent()};

const wireContentBase=wireContent;
wireContent=function(){wireContentBase();content.querySelectorAll('[data-quiz]').forEach(q=>{const c=chapters.find(x=>x.id===q.dataset.quiz);if(!c)return;const feedback=q.querySelector('.quiz-feedback');let stage=0;let firstCorrect=false;const options=[...q.querySelectorAll('.quiz-option')];options.forEach(opt=>opt.onclick=()=>{if(stage!==0)return;firstCorrect=+opt.dataset.answer===c.quiz.answer;opt.classList.add(firstCorrect?'correct':'wrong');if(!firstCorrect)q.querySelector(`[data-answer="${c.quiz.answer}"]`)?.classList.add('correct');q.dataset.answered='yes';const stat=state.quizStats[c.id]||{right:0,wrong:0};stat[firstCorrect?'right':'wrong']++;state.quizStats[c.id]=stat;storage.set(STORAGE,JSON.stringify(state));feedback.textContent=(firstCorrect?'Bonne réponse. ':'Pas tout à fait. ')+c.quiz.explain;const follow=document.createElement('div');follow.className='adaptive-followup';const right=firstCorrect?c.advanced:c.analogy;const distractor=firstCorrect?c.simple:c.problem;follow.innerHTML=`<div class="adaptive-head"><span class="eyebrow">${firstCorrect?'DÉFI APPROFONDI':'RAPPEL GUIDÉ'} · ÉTAPE 2/2</span><h3>${firstCorrect?'À présent, quel principe faut-il garder en tête ?':'Quelle idée vous aide à reconnaître ce concept ?'}</h3></div><button class="quiz-option" data-follow="right">${right}</button><button class="quiz-option" data-follow="wrong">${distractor}</button><div class="quiz-feedback"></div>`;q.append(follow);stage=1;follow.querySelectorAll('[data-follow]').forEach(answer=>answer.onclick=()=>{if(stage!==1)return;stage=2;const correctAnswer=answer.dataset.follow==='right';answer.classList.add(correctAnswer?'correct':'wrong');if(!correctAnswer)follow.querySelector('[data-follow="right"]').classList.add('correct');const second=state.quizStats[c.id];second[correctAnswer?'right':'wrong']++;storage.set(STORAGE,JSON.stringify(state));follow.querySelector('.quiz-feedback').textContent=correctAnswer?'Bien vu. Vous reliez maintenant la notion à son application.':'Relisez l’explication puis réessayez dans une prochaine révision.';q.dataset.answered='complete';if(firstCorrect&&correctAnswer&&!state.quizBonus?.includes(c.id)){state.quizBonus||=[];state.quizBonus.push(c.id);state.xp+=5;save();toast('Quiz maîtrisé · +5 XP')}else updateStats()})})})};

const wireAdaptiveOrderBase=wireContent;
wireContent=function(){wireAdaptiveOrderBase();content.querySelectorAll('[data-quiz]').forEach(q=>{const c=chapters.find(x=>x.id===q.dataset.quiz);if(!c)return;const chapterNumber=Number.isInteger(Number(c.id))?Number(c.id):Number(c.id.split('.').pop());q.querySelectorAll('.quiz-option[data-answer]').forEach(option=>{const previous=option.onclick;option.onclick=function(event){previous.call(this,event);const follow=q.querySelector('.adaptive-followup');if(follow&&chapterNumber%2===0)follow.append(follow.querySelector('[data-follow="right"]'))}})})};

function saveAcademyRoute(route){const hash='#'+route,previous=location.hash.slice(1)||'home';state.lastRoute=route;state.lastScrollY=0;storage.set(STORAGE,JSON.stringify(state));if(location.hash===hash)return false;try{history.replaceState({...history.state,academyRoute:previous,academyScrollY:window.scrollY},'',location.href);history.pushState({academyRoute:route,academyScrollY:0},'',hash);return true}catch{ignoreAcademyHash=true;location.hash=route;return true}}
let ignoreAcademyHash=false;
function withAcademyRoute(fn,getRoute){return function(...args){const result=fn.apply(this,args),route=getRoute(...args),changed=saveAcademyRoute(route);if(changed)window.scrollTo(0,0);return result}}
renderHome=withAcademyRoute(renderHome,()=> 'home');showModule=withAcademyRoute(showModule,id=>'module/'+id);renderLesson=withAcademyRoute(renderLesson,c=>'lesson/'+encodeURIComponent(c.id));renderPath=withAcademyRoute(renderPath,()=> 'path');renderMindmap=withAcademyRoute(renderMindmap,()=> 'mindmap');renderGlossary=withAcademyRoute(renderGlossary,()=> 'glossary');renderSaved=withAcademyRoute(renderSaved,()=> 'saved');renderHistory=withAcademyRoute(renderHistory,()=> 'history');renderAchievements=withAcademyRoute(renderAchievements,()=> 'achievements');renderSearch=withAcademyRoute(renderSearch,q=>{state.searchTerm=q;return 'search'});
function renderAcademyRoute(route){const [view,...parts]=route.split('/');if(view==='lesson'){let id;try{id=decodeURIComponent(parts.join('/'))}catch{}const chapter=chapters.find(c=>c.id===id);return chapter?renderLesson(chapter):renderHome()}if(view==='module'){const id=Number(parts[0]);return modules.some(m=>m.id===id)?showModule(id):renderHome()}if(view==='search'){const q=state.searchTerm||'';$('#searchInput').value=q;return q?renderSearch(q):renderHome()}if(['home','path','mindmap','glossary','saved','history','achievements'].includes(view))return navigate(view);return renderHome()}
function restoreAcademyRoute(){const route=location.hash.slice(1)||state.lastRoute||'home';state.lastRoute=route;storage.set(STORAGE,JSON.stringify(state));renderAcademyRoute(route);const savedY=history.state?.academyRoute===route?history.state.academyScrollY:state.lastScrollY||0;requestAnimationFrame(()=>window.scrollTo(0,Number(savedY)||0))}
window.addEventListener('pagehide',()=>{state.lastRoute=location.hash.slice(1)||state.lastRoute||'home';state.lastScrollY=window.scrollY;storage.set(STORAGE,JSON.stringify(state));try{history.replaceState({...history.state,academyRoute:state.lastRoute,academyScrollY:window.scrollY},'',location.href)}catch{}});
window.addEventListener('popstate',event=>{const route=location.hash.slice(1)||event.state?.academyRoute||'home';state.lastRoute=route;storage.set(STORAGE,JSON.stringify(state));renderAcademyRoute(route);requestAnimationFrame(()=>window.scrollTo(0,Number(event.state?.academyScrollY)||0))});
window.addEventListener('hashchange',()=>{if(ignoreAcademyHash){ignoreAcademyHash=false;return}const route=location.hash.slice(1)||'home';state.lastRoute=route;storage.set(STORAGE,JSON.stringify(state));renderAcademyRoute(route)});
buildModuleNav();updateStats();restoreAcademyRoute();
const themeSelect=$('#themeSelect');
function applyTheme(theme,persist=false){const allowed=['midnight','light','ocean'];const selected=allowed.includes(theme)?theme:'midnight';document.documentElement.dataset.theme=selected;themeSelect.value=selected;if(persist){state.theme=selected;storage.set(STORAGE,JSON.stringify(state))}}
applyTheme(state.theme||'midnight');
themeSelect.onchange=()=>applyTheme(themeSelect.value,true);
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>{closeMobileSidebar();navigate(b.dataset.view)});$('#notesOpen').onclick=openNotes;
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=e=>{e.preventDefault();b.closest('dialog').close()});
$('#notesText').oninput=e=>{state.notes=e.target.value;save();$('#notesSaved').textContent='Sauvegardé à l’instant'};
$('#searchInput').oninput=e=>{const v=e.target.value.trim();if(v.length>1)renderSearch(v);else if(!v)renderHome()};$('#searchInput').onkeydown=e=>{if(e.key==='Escape'){e.target.value='';renderHome()}};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchInput').focus();if(innerWidth<560)$('#searchInput').closest('.search-box').classList.add('expanded')}});
$('#searchInput').addEventListener('focus',()=>{if(innerWidth<560)$('#searchInput').closest('.search-box').classList.add('expanded')});$('#searchInput').addEventListener('blur',()=>{if(innerWidth<560&&!$('#searchInput').value)$('#searchInput').closest('.search-box').classList.remove('expanded')});
$('#menuToggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menuToggle').setAttribute('aria-expanded',String(open));$('#menuToggle').setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu')};document.addEventListener('click',e=>{if(innerWidth<800&&$('#sidebar').classList.contains('open')&&!$('#sidebar').contains(e.target)&&!$('#menuToggle').contains(e.target))closeMobileSidebar()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMobileSidebar()});
const moduleNavToggle=$('#moduleNavToggle'),moduleNav=$('#moduleNav');moduleNavToggle.onclick=()=>{const expanded=moduleNavToggle.getAttribute('aria-expanded')==='true';moduleNavToggle.setAttribute('aria-expanded',String(!expanded));moduleNav.hidden=expanded};document.querySelector('.brand').onclick=e=>{e.preventDefault();renderHome()};
